require_once __DIR__.'/../config/constants.php';$me=require_admin();if(!is_post())redirect('admin/manage-admin.php');verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id)redirect('admin/manage-admin.php');if((int)$me['id']===$id){flash('error','You cannot delete the admin account you are currently using.');redirect('admin/manage-admin.php');}$count=(int)db()->query('SELECT COUNT(*) FROM tbl_admin')->fetchColumn();if($count<=1){flash('error','At least one administrator must remain.');redirect('admin/manage-admin.php');}$stmt=db()->prepare('DELETE FROM tbl_admin WHERE id=?');$stmt->execute([$id]);flash('success','Admin deleted.');redirect('admin/manage-admin.php');
